/// Engine that owns message transfer from a prost message into a destination.
///
/// The trait is intentionally separate from [`Message`], so generated structs
/// and existing synchronous call sites do not grow hardware-specific methods or
/// required async hooks.
pub trait EncodeEngine: Clone + Send + Sync + 'static {
    /// Error produced while starting or completing an encode operation.
    type Error: From<EncodeError> + Send + Sync + 'static;

    /// Owned future returned for one encode operation.
    type Encode<M, B>: Future<Output = Result<B, Self::Error>> + Send + 'static
    where
        M: Message + Send + 'static,
        B: EncodeDst + Send + 'static;

    /// Starts encoding `message` into owned destination `dst`.
    fn encode<M, B>(
        &self,
        message: M,
        dst: B,
        options: EncodeOptions,
    ) -> Result<Self::Encode<M, B>, Self::Error>
    where
        M: Message + Send + 'static,
        B: EncodeDst + Send + 'static;
}

/// CPU-backed encode engine using prost's existing synchronous [`Message`] API.
#[derive(Clone, Copy, Debug, Default)]
pub struct CpuEngine;

/// Ready future returned by [`CpuEngine`].
#[derive(Debug)]
pub struct CpuEncode<B> {
    result: Option<Result<B, EncodeError>>,
}

impl<B> CpuEncode<B> {
    #[inline]
    fn new(result: Result<B, EncodeError>) -> Self {
        Self {
            result: Some(result),
        }
    }

    /// Consumes this ready future and returns the encoded destination.
    ///
    /// This is useful for adapters that must preserve a synchronous ready fast
    /// path while still routing encoding through [`EncodeEngine`].
    #[inline]
    pub fn into_result(mut self) -> Result<B, EncodeError> {
        self.result
            .take()
            .expect("CpuEncode polled or consumed after completion")
    }
}

impl<B> Unpin for CpuEncode<B> {}

impl<B> Future for CpuEncode<B> {
    type Output = Result<B, EncodeError>;

    #[inline]
    fn poll(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<Self::Output> {
        Poll::Ready(
            self.get_mut()
                .result
                .take()
                .expect("CpuEncode polled after completion"),
        )
    }
}

impl EncodeEngine for CpuEngine {
    type Error = EncodeError;

    type Encode<M, B>
        = CpuEncode<B>
    where
        M: Message + Send + 'static,
        B: EncodeDst + Send + 'static;

    #[inline]
    fn encode<M, B>(
        &self,
        message: M,
        mut dst: B,
        options: EncodeOptions,
    ) -> Result<Self::Encode<M, B>, Self::Error>
    where
        M: Message + Send + 'static,
        B: EncodeDst + Send + 'static,
    {
        let result = {
            let mut buf = dst.as_buf_mut();
            if options.length_delimited {
                message.encode_length_delimited(&mut buf)
            } else {
                message.encode(&mut buf)
            }
        };

        Ok(CpuEncode::new(result.map(|()| dst)))
    }
}

#[cfg(not(feature = "std"))]
use alloc::boxed::Box;
#[cfg(not(feature = "std"))]
use alloc::vec::Vec;

use bytes::{Buf, BufMut};
use core::task::{Context, Poll};

use crate::encoding::varint::{encode_varint, encoded_len_varint};
use crate::encoding::wire_type::WireType;
use crate::encoding::{decode_key, message, DecodeContext};
use crate::transfer::{AsyncEncodeSink, EncodeRawAsync, PollEncodeState};
use crate::DecodeError;
use crate::EncodeError;

/// A Protocol Buffers message.
pub trait Message: Send + Sync {
    /// Encodes the message to a buffer.
    ///
    /// This method will panic if the buffer has insufficient capacity.
    ///
    /// Meant to be used only by `Message` implementations.
    #[doc(hidden)]
    fn encode_raw(&self, buf: &mut impl BufMut)
    where
        Self: Sized;

    /// Polls message-body encoding into an asynchronous encode sink.
    ///
    /// The default implementation delegates to [`Message::encode_raw`]. Derived
    /// messages override this method so `string` and `bytes` payload copies can
    /// suspend while the rest of the protobuf structure remains CPU-encoded.
    #[doc(hidden)]
    fn poll_encode_raw<S>(
        &self,
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        _cx: &mut Context<'_>,
    ) -> Poll<Result<(), S::Error>>
    where
        Self: Sized,
        S: AsyncEncodeSink + Send,
    {
        if state.field() == 0 {
            let mut buf = sink.buf_mut();
            self.encode_raw(&mut buf);
        }
        state.clear();
        Poll::Ready(Ok(()))
    }

    /// Encodes the message body to an asynchronous encode sink.
    ///
    /// This future-shaped adapter drives [`Message::poll_encode_raw`] for code
    /// that already owns an async encode boundary.
    #[doc(hidden)]
    fn encode_raw_async<'a, S>(&'a self, sink: &'a mut S) -> EncodeRawAsync<'a, Self, S>
    where
        Self: Sized + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
        EncodeRawAsync::new(self, sink)
    }

    /// Decodes a field from a buffer, and merges it into `self`.
    ///
    /// Meant to be used only by `Message` implementations.
    #[doc(hidden)]
    fn merge_field(
        &mut self,
        tag: u32,
        wire_type: WireType,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        Self: Sized;

    /// Returns the encoded length of the message without a length delimiter.
    fn encoded_len(&self) -> usize;

    /// Encodes the message to a buffer.
    ///
    /// An error will be returned if the buffer does not have sufficient capacity.
    fn encode(&self, buf: &mut impl BufMut) -> Result<(), EncodeError>
    where
        Self: Sized,
    {
        let required = self.encoded_len();
        let remaining = buf.remaining_mut();
        if required > remaining {
            return Err(EncodeError::new(required, remaining));
        }

        self.encode_raw(buf);
        Ok(())
    }

    /// Encodes the message to a newly allocated buffer.
    fn encode_to_vec(&self) -> Vec<u8>
    where
        Self: Sized,
    {
        let mut buf = Vec::with_capacity(self.encoded_len());

        self.encode_raw(&mut buf);
        buf
    }

    /// Encodes the message with a length-delimiter to a buffer.
    ///
    /// An error will be returned if the buffer does not have sufficient capacity.
    fn encode_length_delimited(&self, buf: &mut impl BufMut) -> Result<(), EncodeError>
    where
        Self: Sized,
    {
        let len = self.encoded_len();
        let required = len + encoded_len_varint(len as u64);
        let remaining = buf.remaining_mut();
        if required > remaining {
            return Err(EncodeError::new(required, remaining));
        }
        encode_varint(len as u64, buf);
        self.encode_raw(buf);
        Ok(())
    }

    /// Encodes the message with a length-delimiter to a newly allocated buffer.
    fn encode_length_delimited_to_vec(&self) -> Vec<u8>
    where
        Self: Sized,
    {
        let len = self.encoded_len();
        let mut buf = Vec::with_capacity(len + encoded_len_varint(len as u64));

        encode_varint(len as u64, &mut buf);
        self.encode_raw(&mut buf);
        buf
    }

    /// Decodes an instance of the message from a buffer.
    ///
    /// The entire buffer will be consumed.
    fn decode(mut buf: impl Buf) -> Result<Self, DecodeError>
    where
        Self: Default,
    {
        let mut message = Self::default();
        Self::merge(&mut message, &mut buf).map(|_| message)
    }

    /// Decodes a length-delimited instance of the message from the buffer.
    fn decode_length_delimited(buf: impl Buf) -> Result<Self, DecodeError>
    where
        Self: Default,
    {
        let mut message = Self::default();
        message.merge_length_delimited(buf)?;
        Ok(message)
    }

    /// Decodes an instance of the message from a buffer, and merges it into `self`.
    ///
    /// The entire buffer will be consumed.
    fn merge(&mut self, mut buf: impl Buf) -> Result<(), DecodeError>
    where
        Self: Sized,
    {
        let ctx = DecodeContext::default();
        while buf.has_remaining() {
            let (tag, wire_type) = decode_key(&mut buf)?;
            self.merge_field(tag, wire_type, &mut buf, ctx.clone())?;
        }
        Ok(())
    }

    /// Decodes a length-delimited instance of the message from buffer, and
    /// merges it into `self`.
    fn merge_length_delimited(&mut self, mut buf: impl Buf) -> Result<(), DecodeError>
    where
        Self: Sized,
    {
        message::merge(
            WireType::LengthDelimited,
            self,
            &mut buf,
            DecodeContext::default(),
        )
    }

    /// Clears the message, resetting all fields to their default.
    fn clear(&mut self);
}

impl<M> Message for Box<M>
where
    M: Message,
{
    fn encode_raw(&self, buf: &mut impl BufMut) {
        (**self).encode_raw(buf)
    }
    fn poll_encode_raw<S>(
        &self,
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut Context<'_>,
    ) -> Poll<Result<(), S::Error>>
    where
        Self: Sized,
        S: AsyncEncodeSink + Send,
    {
        (**self).poll_encode_raw(sink, state, cx)
    }
    fn merge_field(
        &mut self,
        tag: u32,
        wire_type: WireType,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError> {
        (**self).merge_field(tag, wire_type, buf, ctx)
    }
    fn encoded_len(&self) -> usize {
        (**self).encoded_len()
    }
    fn clear(&mut self) {
        (**self).clear()
    }
}

