/// Macro which emits encoding functions for a length-delimited type.
macro_rules! length_delimited {
    ($ty:ty) => {
        encode_repeated!($ty);

        pub fn merge_repeated(
            wire_type: WireType,
            values: &mut Vec<$ty>,
            buf: &mut impl Buf,
            ctx: DecodeContext,
        ) -> Result<(), DecodeError> {
            check_wire_type(WireType::LengthDelimited, wire_type)?;
            let mut value = Default::default();
            merge(wire_type, &mut value, buf, ctx)?;
            values.push(value);
            Ok(())
        }

        #[inline]
        #[allow(clippy::ptr_arg)]
        pub fn encoded_len(tag: u32, value: &$ty) -> usize {
            key_len(tag) + encoded_len_varint(value.len() as u64) + value.len()
        }

        #[inline]
        pub fn encoded_len_repeated(tag: u32, values: &[$ty]) -> usize {
            key_len(tag) * values.len()
                + values
                    .iter()
                    .map(|value| encoded_len_varint(value.len() as u64) + value.len())
                    .sum::<usize>()
        }
    };
}

pub mod string {
    use super::*;

    pub fn encode(tag: u32, value: &String, buf: &mut impl BufMut) {
        encode_key(tag, WireType::LengthDelimited, buf);
        encode_varint(value.len() as u64, buf);
        buf.put_slice(value.as_bytes());
    }

    pub fn encode_async<'a, S>(
        tag: u32,
        value: &'a String,
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, S>
    where
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            {
                let mut buf = sink.buf_mut();
                encode_key(tag, WireType::LengthDelimited, &mut buf);
                encode_varint(value.len() as u64, &mut buf);
            }
            sink.put_payload(value.as_bytes()).await
        }
    }

    pub fn poll_encode<S>(
        tag: u32,
        value: &String,
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        S: AsyncEncodeSink + Send,
    {
        if state.phase() == 0 {
            let mut buf = sink.buf_mut();
            encode_key(tag, WireType::LengthDelimited, &mut buf);
            encode_varint(value.len() as u64, &mut buf);
            state.set_phase(1);
        }

        match sink.poll_put_payload(value.as_bytes(), state.payload_pin_mut(), cx) {
            core::task::Poll::Ready(Ok(())) => {
                state.set_phase(0);
                core::task::Poll::Ready(Ok(()))
            }
            core::task::Poll::Ready(Err(error)) => core::task::Poll::Ready(Err(error)),
            core::task::Poll::Pending => core::task::Poll::Pending,
        }
    }

    pub fn poll_encode_repeated<S>(
        tag: u32,
        values: &[String],
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        S: AsyncEncodeSink + Send,
    {
        while state.index() < values.len() {
            let index = state.index();
            match poll_encode(tag, &values[index], sink, state, cx) {
                core::task::Poll::Ready(Ok(())) => state.set_index(index + 1),
                core::task::Poll::Ready(Err(error)) => return core::task::Poll::Ready(Err(error)),
                core::task::Poll::Pending => return core::task::Poll::Pending,
            }
        }

        state.set_index(0);
        core::task::Poll::Ready(Ok(()))
    }

    pub fn encode_repeated_async<'a, S>(
        tag: u32,
        values: &'a [String],
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, S>
    where
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            for value in values {
                encode_async(tag, value, sink).await?;
            }
            Ok(())
        }
    }

    pub fn merge(
        wire_type: WireType,
        value: &mut String,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError> {
        // ## Unsafety
        //
        // `string::merge` reuses `bytes::merge`, with an additional check of utf-8
        // well-formedness. If the utf-8 is not well-formed, or if any other error occurs, then the
        // string is cleared, so as to avoid leaking a string field with invalid data.
        //
        // This implementation uses the unsafe `String::as_mut_vec` method instead of the safe
        // alternative of temporarily swapping an empty `String` into the field, because it results
        // in up to 10% better performance on the protobuf message decoding benchmarks.
        //
        // It's required when using `String::as_mut_vec` that invalid utf-8 data not be leaked into
        // the backing `String`. To enforce this, even in the event of a panic in `bytes::merge` or
        // in the buf implementation, a drop guard is used.
        unsafe {
            struct DropGuard<'a>(&'a mut Vec<u8>);
            impl Drop for DropGuard<'_> {
                #[inline]
                fn drop(&mut self) {
                    self.0.clear();
                }
            }

            let drop_guard = DropGuard(value.as_mut_vec());
            bytes::merge_one_copy(wire_type, drop_guard.0, buf, ctx)?;
            match str::from_utf8(drop_guard.0) {
                Ok(_) => {
                    // Success; do not clear the bytes.
                    mem::forget(drop_guard);
                    Ok(())
                }
                Err(_) => Err(DecodeErrorKind::InvalidString.into()),
            }
        }
    }

    length_delimited!(String);

    #[cfg(test)]
    mod test {
        use proptest::prelude::*;

        use super::super::test::{check_collection_type, check_type};
        use super::*;

        proptest! {
            #[test]
            fn check(value: String, tag in MIN_TAG..=MAX_TAG) {
                super::test::check_type(value, tag, WireType::LengthDelimited,
                                        encode, merge, encoded_len)?;
            }
            #[test]
            fn check_repeated(value: Vec<String>, tag in MIN_TAG..=MAX_TAG) {
                super::test::check_collection_type(value, tag, WireType::LengthDelimited,
                                                   encode_repeated, merge_repeated,
                                                   encoded_len_repeated)?;
            }
        }
    }
}
