    use crate::error::DecodeErrorKind;

    use super::*;

    pub fn encode(tag: u32, value: &impl BytesAdapter, buf: &mut impl BufMut) {
        encode_key(tag, WireType::LengthDelimited, buf);
        encode_varint(value.len() as u64, buf);
        value.append_to(buf);
    }

    pub fn encode_async<'a, T, S>(
        tag: u32,
        value: &'a T,
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, T, S>
    where
        T: BytesAdapter + Sync + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            {
                let mut buf = sink.buf_mut();
                encode_key(tag, WireType::LengthDelimited, &mut buf);
                encode_varint(value.len() as u64, &mut buf);
            }
            sink.put_payload(value.as_slice()).await
        }
    }

    pub fn poll_encode<T, S>(
        tag: u32,
        value: &T,
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        T: BytesAdapter + Sync,
        S: AsyncEncodeSink + Send,
    {
        if state.phase() == 0 {
            let mut buf = sink.buf_mut();
            encode_key(tag, WireType::LengthDelimited, &mut buf);
            encode_varint(value.len() as u64, &mut buf);
            state.set_phase(1);
        }

        match sink.poll_put_payload(value.as_slice(), state.payload_pin_mut(), cx) {
            core::task::Poll::Ready(Ok(())) => {
                state.set_phase(0);
                core::task::Poll::Ready(Ok(()))
            }
            core::task::Poll::Ready(Err(error)) => core::task::Poll::Ready(Err(error)),
            core::task::Poll::Pending => core::task::Poll::Pending,
        }
    }

    pub fn poll_encode_repeated<T, S>(
        tag: u32,
        values: &[T],
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        T: BytesAdapter + Sync,
        S: AsyncEncodeSink + Send,
    {
        while state.index() < values.len() {
            let index = state.index();
            match poll_encode(tag, &values[index], sink, state, cx) {
                core::task::Poll::Ready(Ok(())) => state.set_index(index + 1),
                core::task::Poll::Ready(Err(error)) => return core::task::Poll::Ready(Err(error)),
                core::task::Poll::Pending => return core::task::Poll::Pending,
            }
        }

        state.set_index(0);
        core::task::Poll::Ready(Ok(()))
    }

    pub fn encode_repeated_async<'a, T, S>(
        tag: u32,
        values: &'a [T],
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, T, S>
    where
        T: BytesAdapter + Sync + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            for value in values {
                encode_async(tag, value, sink).await?;
            }
            Ok(())
        }
    }

    pub fn merge(
        wire_type: WireType,
        value: &mut impl BytesAdapter,
        buf: &mut impl Buf,
        _ctx: DecodeContext,
    ) -> Result<(), DecodeError> {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        let len = decode_varint(buf)?;
        if len > buf.remaining() as u64 {
            return Err(DecodeErrorKind::BufferUnderflow.into());
        }
        let len = len as usize;

        // Clear the existing value. This follows from the following rule in the encoding guide[1]:
        //
        // > Normally, an encoded message would never have more than one instance of a non-repeated
        // > field. However, parsers are expected to handle the case in which they do. For numeric
        // > types and strings, if the same field appears multiple times, the parser accepts the
        // > last value it sees.
        //
        // [1]: https://protobuf.dev/programming-guides/encoding/#last-one-wins
        //
        // This is intended for A and B both being Bytes so it is zero-copy.
        // Some combinations of A and B types may cause a double-copy,
        // in which case merge_one_copy() should be used instead.
        value.replace_with(buf.copy_to_bytes(len));
        Ok(())
    }

    pub(super) fn merge_one_copy(
        wire_type: WireType,
        value: &mut impl BytesAdapter,
        buf: &mut impl Buf,
        _ctx: DecodeContext,
    ) -> Result<(), DecodeError> {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        let len = decode_varint(buf)?;
        if len > buf.remaining() as u64 {
            return Err(DecodeErrorKind::BufferUnderflow.into());
        }
        let len = len as usize;

        // If we must copy, make sure to copy only once.
        value.replace_with(buf.take(len));
        Ok(())
    }

    length_delimited!(impl BytesAdapter);

    #[cfg(test)]
    mod test {
        use proptest::prelude::*;

        use super::super::test::{check_collection_type, check_type};
        use super::*;

        proptest! {
            #[test]
            fn check_vec(value: Vec<u8>, tag in MIN_TAG..=MAX_TAG) {
                super::test::check_type::<Vec<u8>, Vec<u8>>(value, tag, WireType::LengthDelimited,
                                                            encode, merge, encoded_len)?;
            }

            #[test]
            fn check_bytes(value: Vec<u8>, tag in MIN_TAG..=MAX_TAG) {
                let value = Bytes::from(value);
                super::test::check_type::<Bytes, Bytes>(value, tag, WireType::LengthDelimited,
                                                        encode, merge, encoded_len)?;
            }

            #[test]
            fn check_repeated_vec(value: Vec<Vec<u8>>, tag in MIN_TAG..=MAX_TAG) {
                super::test::check_collection_type(value, tag, WireType::LengthDelimited,
                                                   encode_repeated, merge_repeated,
                                                   encoded_len_repeated)?;
            }

            #[test]
            fn check_repeated_bytes(value: Vec<Vec<u8>>, tag in MIN_TAG..=MAX_TAG) {
                let value = value.into_iter().map(Bytes::from).collect();
                super::test::check_collection_type(value, tag, WireType::LengthDelimited,
                                                   encode_repeated, merge_repeated,
                                                   encoded_len_repeated)?;
            }
        }
    }
