pub mod message {
    use super::*;

    pub fn encode<M>(tag: u32, msg: &M, buf: &mut impl BufMut)
    where
        M: Message,
    {
        encode_key(tag, WireType::LengthDelimited, buf);
        encode_varint(msg.encoded_len() as u64, buf);
        msg.encode_raw(buf);
    }

    pub fn encode_async<'a, M, S>(
        tag: u32,
        msg: &'a M,
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, M, S>
    where
        M: Message + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            {
                let mut buf = sink.buf_mut();
                encode_key(tag, WireType::LengthDelimited, &mut buf);
                encode_varint(msg.encoded_len() as u64, &mut buf);
            }
            msg.encode_raw_async(sink).await
        }
    }

    pub fn poll_encode<S, M>(
        tag: u32,
        msg: &M,
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        S: AsyncEncodeSink + Send,
        M: Message,
    {
        poll_encode_with_phases(tag, msg, sink, state, cx, 0, 1, 0)
    }

    pub fn poll_encode_with_phases<S, M>(
        tag: u32,
        msg: &M,
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
        start_phase: u8,
        nested_phase: u8,
        next_phase: u8,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        S: AsyncEncodeSink + Send,
        M: Message,
    {
        if state.phase() == start_phase {
            {
                let mut buf = sink.buf_mut();
                encode_key(tag, WireType::LengthDelimited, &mut buf);
                encode_varint(msg.encoded_len() as u64, &mut buf);
            }
            state.set_phase(nested_phase);
        }

        state.enter_nested();
        match msg.poll_encode_raw(sink, state, cx) {
            core::task::Poll::Ready(Ok(())) => {
                state.leave_nested_ready();
                state.set_phase(next_phase);
                core::task::Poll::Ready(Ok(()))
            }
            core::task::Poll::Ready(Err(error)) => {
                state.leave_nested_ready();
                core::task::Poll::Ready(Err(error))
            }
            core::task::Poll::Pending => {
                state.leave_nested_pending();
                core::task::Poll::Pending
            }
        }
    }

    pub fn merge<M, B>(
        wire_type: WireType,
        msg: &mut M,
        buf: &mut B,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        M: Message,
        B: Buf,
    {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        ctx.limit_reached()?;
        merge_loop(
            msg,
            buf,
            ctx.enter_recursion(),
            |msg: &mut M, buf: &mut B, ctx| {
                let (tag, wire_type) = decode_key(buf)?;
                msg.merge_field(tag, wire_type, buf, ctx)
            },
        )
    }

    pub fn encode_repeated<M>(tag: u32, messages: &[M], buf: &mut impl BufMut)
    where
        M: Message,
    {
        for msg in messages {
            encode(tag, msg, buf);
        }
    }

    pub fn encode_repeated_async<'a, M, S>(
        tag: u32,
        messages: &'a [M],
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, M, S>
    where
        M: Message + 'a,
        S: AsyncEncodeSink + Send + 'a,
    {
        async move {
            for msg in messages {
                encode_async(tag, msg, sink).await?;
            }
            Ok(())
        }
    }

    pub fn poll_encode_repeated<S, M>(
        tag: u32,
        messages: &[M],
        sink: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut core::task::Context<'_>,
    ) -> core::task::Poll<Result<(), S::Error>>
    where
        S: AsyncEncodeSink + Send,
        M: Message,
    {
        while state.index() < messages.len() {
            let index = state.index();
            match poll_encode(tag, &messages[index], sink, state, cx) {
                core::task::Poll::Ready(Ok(())) => state.set_index(index + 1),
                core::task::Poll::Ready(Err(error)) => return core::task::Poll::Ready(Err(error)),
                core::task::Poll::Pending => return core::task::Poll::Pending,
            }
        }

        state.set_index(0);
        core::task::Poll::Ready(Ok(()))
    }

    pub fn merge_repeated<M>(
        wire_type: WireType,
        messages: &mut Vec<M>,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError>
    where
        M: Message + Default,
    {
        check_wire_type(WireType::LengthDelimited, wire_type)?;
        let mut msg = M::default();
        merge(WireType::LengthDelimited, &mut msg, buf, ctx)?;
        messages.push(msg);
        Ok(())
    }

    #[inline]
    pub fn encoded_len<M>(tag: u32, msg: &M) -> usize
    where
        M: Message,
    {
        let len = msg.encoded_len();
        key_len(tag) + encoded_len_varint(len as u64) + len
    }

    #[inline]
    pub fn encoded_len_repeated<M>(tag: u32, messages: &[M]) -> usize
    where
        M: Message,
    {
        key_len(tag) * messages.len()
            + messages
                .iter()
                .map(Message::encoded_len)
                .map(|len| len + encoded_len_varint(len as u64))
                .sum::<usize>()
    }
