231:{
232:    type Output = Result<EncodeBuffer, Status>;
233:
234:    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
235:        // SAFETY: once tonic polls this future, the poll encode state remains
236:        // in place until the future completes or is dropped.
237:        let this = unsafe { self.get_unchecked_mut() };
238:
239:        loop {
240:            match this.stage {
241:                DsaAsyncProstEncodeStage::Start => {
242:                    let item = this.item.as_ref().expect("encode item present");
243:                    let sink = this.sink.as_mut().expect("encode sink present");
244:                    let len = item.encoded_len();
245:                    let required = if this.options.length_delimited {
246:                        len + encoded_len_varint(len as u64)
247:                    } else {
248:                        len
249:                    };
250:                    let remaining = {
251:                        let buf = sink.buf_mut();
252:                        buf.remaining_mut()
253:                    };
254:                    if required > remaining {
255:                        this.stage = DsaAsyncProstEncodeStage::Done;
256:                        return Poll::Ready(Err(Status::internal(format!(
257:                            "failed to encode Protobuf message; insufficient buffer capacity (required: {required}, remaining: {remaining})"
258:                        ))));
259:                    }
260:
261:                    if this.options.length_delimited {
262:                        let mut buf = sink.buf_mut();
263:                        encode_varint(len as u64, &mut buf);
264:                    }
265:                    this.stage = DsaAsyncProstEncodeStage::Body;
266:                }
267:                DsaAsyncProstEncodeStage::Body => {
268:                    let item = this.item.as_ref().expect("encode item present");
269:                    let sink = this.sink.as_mut().expect("encode sink present");
270:                    match item.poll_encode_raw(sink, &mut this.state, cx) {
271:                        Poll::Ready(Ok(())) => {
272:                            this.stage = DsaAsyncProstEncodeStage::Done;
273:                            this.item.take();
274:                            let sink = this.sink.take().expect("encode sink present");
275:                            return Poll::Ready(Ok(sink.into_inner()));
276:                        }
277:                        Poll::Ready(Err(status)) => {
278:                            this.stage = DsaAsyncProstEncodeStage::Done;
279:                            return Poll::Ready(Err(status));
280:                        }
281:                        Poll::Pending => return Poll::Pending,
282:                    }
283:                }
284:                DsaAsyncProstEncodeStage::Done => {
285:                    panic!("DsaAsyncProstEncode polled after completion")
286:                }
287:            }
288:        }
289:    }
