555:impl PendingDsaProstPayloadCopy {
556:    fn new(work_queue: SharedDsaWorkQueue) -> Self {
557:        Self {
558:            work_queue,
559:            source: core::ptr::null(),
560:            source_len: 0,
561:            dst: std::ptr::null_mut(),
562:            dst_len: 0,
563:            desc: DsaHwDesc::default(),
564:            completion: DsaCompletionRecord::default(),
565:            retry: None,
566:            submitted: false,
567:            completed: false,
568:            _pin: PhantomPinned,
569:        }
570:    }
571:
572:    fn poll(
573:        mut self: Pin<&mut Self>,
574:        source: &[u8],
575:        buf: &mut EncodeBuffer,
576:        cx: &mut Context<'_>,
577:    ) -> Poll<Result<(), Status>> {
578:        // SAFETY: This method never moves fields out of the pinned state. It
579:        // only mutates scalar state and borrows the owned descriptor,
580:        // completion record, and encode buffer in place.
581:        let this = unsafe { self.as_mut().get_unchecked_mut() };
582:
583:        if !this.submitted {
584:            let len = source.len();
585:            let mut dst = buf.as_encode_buf();
586:            // SAFETY: The pending state has exclusive access to the encode
587:            // buffer through the poll call until completion. The matching
588:            // advance happens exactly once after DSA reports success.
589:            let dst_ptr = unsafe { dst.reserve_uninit_slice_for_pending(len) };
590:            touch_pages_for_dsa(source.as_ptr(), dst_ptr, len);
591:
592:            let retry = DsaMemmoveRetry::new(source.as_ptr(), dst_ptr, len);
593:            submit_retry(
594:                &this.work_queue,
595:                &mut this.desc,
596:                &mut this.completion,
597:                &retry,
598:            )?;
599:            this.retry = Some(retry);
600:            this.source = source.as_ptr();
601:            this.source_len = len;
602:            this.dst = dst_ptr;
603:            this.dst_len = len;
604:            this.submitted = true;
605:        } else {
606:            debug_assert_eq!(this.source, source.as_ptr());
607:            debug_assert_eq!(this.source_len, source.len());
608:        }
609:
610:        if this.completion.status() == DsaCompletionStatus::None.as_u8() {
611:            cx.waker().wake_by_ref();
612:            return Poll::Pending;
613:        }
614:
615:        let retry = this.retry.as_mut().expect("pending retry state available");
616:        match retry.handle_completion(this.completion, &this.work_queue.config.device_path) {
617:            Ok(DsaRetryAction::Complete) => {
618:                this.completed = true;
619:                // SAFETY: DSA success means the descriptor initialized exactly
620:                // the bytes reserved for this payload copy.
621:                unsafe {
622:                    buf.as_encode_buf()
623:                        .advance_reserved_uninit_slice(this.dst_len);
624:                }
625:                Poll::Ready(Ok(()))
626:            }
627:            Ok(DsaRetryAction::Retry) => {
628:                submit_retry(
629:                    &this.work_queue,
630:                    &mut this.desc,
631:                    &mut this.completion,
632:                    retry,
633:                )?;
634:                cx.waker().wake_by_ref();
635:                Poll::Pending
636:            }
