544:    fn fill_desc(&self, desc: &mut DsaHwDesc) -> Result<(), Status> {
545:        if self.remaining > u32::MAX as usize {
546:            return Err(Status::internal(format!(
547:                "async dsa bytes encode cannot copy remaining {} bytes; maximum DSA transfer is {} bytes",
548:                self.remaining,
549:                u32::MAX
550:            )));
551:        }
552:
553:        desc.fill_memmove(self.src, self.dst, self.remaining as u32);
554:        Ok(())
555:    }
