557:    fn handle_completion(
558:        &mut self,
559:        completion: DsaCompletionRecord,
560:        device_path: &PathBuf,
561:    ) -> Result<DsaRetryAction, Status> {
562:        let raw_status = completion.status();
563:        let status = DsaCompletionStatus::mask(raw_status);
564:        if status == DsaCompletionStatus::Success.as_u8() {
565:            return Ok(DsaRetryAction::Complete);
566:        }
567:
568:        if status != DsaCompletionStatus::PageFaultNoBof.as_u8() {
569:            return Err(dsa_completion_error(
570:                "async dsa bytes encode failed",
571:                completion,
572:                self.original_len,
573:                self.remaining,
574:                device_path,
575:            ));
576:        }
577:
578:        self.handle_page_fault(
579:            raw_status,
580:            completion.bytes_completed(),
581:            completion.fault_addr(),
582:            device_path,
583:        )?;
584:        Ok(DsaRetryAction::Retry)
585:    }
586:
587:    fn handle_page_fault(
588:        &mut self,
589:        raw_status: u8,
590:        bytes_completed: u32,
591:        fault_addr: u64,
592:        device_path: &PathBuf,
593:    ) -> Result<(), Status> {
594:        if self.retry_count >= self.max_retries {
595:            return Err(Status::internal(format!(
596:                "async dsa bytes encode page-fault retry limit exceeded on {} for {} bytes: retries={} remaining={} fault_addr={fault_addr:#x}",
597:                device_path.display(),
598:                self.original_len,
599:                self.retry_count,
600:                self.remaining
601:            )));
602:        }
603:
604:        let completed = bytes_completed as usize;
605:        if completed > self.remaining {
606:            return Err(Status::internal(format!(
607:                "async dsa bytes encode page fault on {} reported bytes_completed={} beyond remaining {} for {} byte transfer",
608:                device_path.display(),
609:                completed,
610:                self.remaining,
611:                self.original_len
612:            )));
613:        }
614:
615:        if completed == 0 {
616:            self.no_progress_retry_count += 1;
617:            if self.no_progress_retry_count > MAX_NO_PROGRESS_PAGE_FAULT_RETRIES {
618:                return Err(Status::internal(format!(
619:                    "async dsa bytes encode made no progress after {} page-fault retries on {} for {} bytes: remaining={} fault_addr={fault_addr:#x}",
620:                    self.no_progress_retry_count,
621:                    device_path.display(),
622:                    self.original_len,
623:                    self.remaining
624:                )));
625:            }
626:        } else {
627:            self.no_progress_retry_count = 0;
628:        }
629:
630:        touch_fault_addr(raw_status, fault_addr)?;
631:
632:        if completed == self.remaining {
633:            return Err(Status::internal(format!(
634:                "async dsa bytes encode page fault on {} left no remaining bytes to retry for {} byte transfer",
635:                device_path.display(),
636:                self.original_len
637:            )));
638:        }
639:
640:        // SAFETY: `completed <= self.remaining`, and both pointers describe the
641:        // current still-owned source/destination ranges for this memmove.
642:        unsafe {
643:            self.src = self.src.add(completed);
644:            self.dst = self.dst.add(completed);
645:        }
646:        self.remaining -= completed;
647:        self.retry_count += 1;
648:        Ok(())
649:    }
650:}
