858:fn touch_fault_addr(raw_status: u8, fault_addr: u64) -> Result<(), Status> {
859:    if fault_addr == 0 {
860:        return Err(Status::internal(
861:            "async dsa bytes encode page fault reported a null fault address",
862:        ));
863:    }
864:
865:    let ptr = fault_addr as *mut u8;
866:    if raw_status & DSA_COMP_STATUS_WRITE != 0 {
867:        // SAFETY: DSA reports `fault_addr` as a process virtual address that
868:        // faulted on a write. The destination may be tonic's uninitialized spare
869:        // capacity, so write a byte to fault the page in without first reading
870:        // an uninitialized value. DSA will overwrite the byte when the adjusted
871:        // descriptor is resubmitted.
872:        unsafe {
873:            std::ptr::write_volatile(ptr, 0);
874:        }
875:    } else {
876:        // SAFETY: DSA reports `fault_addr` as a process virtual address that
877:        // faulted on a read. A volatile read is enough to fault the page in.
878:        unsafe {
879:            let _ = std::ptr::read_volatile(ptr.cast_const());
880:        }
881:    }
882:
883:    Ok(())
884:}
