//! Opt-in hardware smoke tests for the asynchronous DSA bytes encoder.

use bytes::Bytes;
use http_body::Body;
use prost::Message as _;
use std::{
    collections::BTreeMap,
    env,
    path::PathBuf,
    pin::pin,
    task::{Context, Poll},
};
use tonic::{
    Status,
    codec::{BufferSettings, EncodeBody, HEADER_SIZE},
};
use tonic_dsa_bytes_async::{DsaAsyncBytesEncoder, DsaAsyncProstEncoder, DsaConfig, DsaWorkQueue};

fn open_test_work_queue() -> tonic_dsa_bytes_async::SharedDsaWorkQueue {
    let device_path = env::var_os("TONIC_DSA_WQ")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/dev/dsa/wq0.0"));
    assert!(
        device_path.exists(),
        "DSA work-queue device does not exist: {}",
        device_path.display()
    );

    DsaWorkQueue::open(DsaConfig::new(device_path.clone()).with_min_message_bytes(1))
        .unwrap_or_else(|err| panic!("failed to open {}: {err}", device_path.display()))
}
#[test]
#[ignore = "requires an enabled /dev/dsa work queue and CAP_SYS_RAWIO"]
fn dsa_work_queue_encodes_one_frame() {
    let work_queue = open_test_work_queue();

    let payload = Bytes::from_static(b"async dsa hardware payload");
    let expected_payload = payload.clone();
    let source = tokio_stream::iter(std::iter::once(Ok::<_, Status>(payload)));
    let mut body = pin!(EncodeBody::new_client(
        DsaAsyncBytesEncoder::with_work_queue(BufferSettings::default(), work_queue),
        source,
        None,
        None,
    ));
    let waker = std::task::Waker::noop();
    let mut cx = Context::from_waker(waker);

    let frame = poll_next_frame(&mut body, &mut cx);
    let data = frame.into_data().expect("got data frame");

    assert_eq!(data[0], 0);
    assert_eq!(
        u32::from_be_bytes(data[1..HEADER_SIZE].try_into().unwrap()) as usize,
        expected_payload.len()
    );
    assert_eq!(&data[HEADER_SIZE..], &expected_payload[..]);
}

#[derive(Clone, PartialEq, prost::Message)]
struct HardwareNestedPayload {
    #[prost(uint32, tag = "1")]
    id: u32,
    #[prost(string, tag = "2")]
    name: String,
    #[prost(bytes = "vec", tag = "3")]
    payload: Vec<u8>,
}

#[derive(Clone, PartialEq, prost::Message)]
struct HardwareProstMessage {
    #[prost(uint32, tag = "1")]
    scalar: u32,
    #[prost(string, tag = "2")]
    name: String,
    #[prost(bytes = "bytes", tag = "3")]
    payload: Bytes,
    #[prost(string, repeated, tag = "4")]
    repeated_names: Vec<String>,
    #[prost(bytes = "vec", repeated, tag = "5")]
    repeated_payloads: Vec<Vec<u8>>,
    #[prost(btree_map = "string, string", tag = "6")]
    string_map: BTreeMap<String, String>,
    #[prost(btree_map = "string, bytes", tag = "7")]
    bytes_map: BTreeMap<String, Vec<u8>>,
    #[prost(message, optional, tag = "8")]
    nested: Option<HardwareNestedPayload>,
    #[prost(message, repeated, tag = "9")]
    repeated_nested: Vec<HardwareNestedPayload>,
    #[prost(btree_map = "string, message", tag = "10")]
    nested_map: BTreeMap<String, HardwareNestedPayload>,
    #[prost(oneof = "HardwarePayloadOneof", tags = "11, 12")]
    payload_oneof: Option<HardwarePayloadOneof>,
    #[prost(oneof = "HardwareNestedOneof", tags = "13, 14")]
    nested_oneof: Option<HardwareNestedOneof>,
}

#[derive(Clone, PartialEq, prost::Oneof)]
enum HardwarePayloadOneof {
    #[prost(bytes = "vec", tag = "11")]
    Payload(Vec<u8>),
    #[prost(string, tag = "12")]
    Text(String),
}

#[derive(Clone, PartialEq, prost::Oneof)]
enum HardwareNestedOneof {
    #[prost(message, tag = "13")]
    Nested(HardwareNestedPayload),
    #[prost(string, tag = "14")]
    Text(String),
}

#[test]
#[ignore = "requires an enabled /dev/dsa work queue and CAP_SYS_RAWIO"]
fn dsa_work_queue_encodes_generated_prost_payload_shapes() {
    let work_queue = open_test_work_queue();

    let nested_a = HardwareNestedPayload {
        id: 7,
        name: "hardware nested a ".repeat(1024),
        payload: vec![0x11; 64 * 1024],
    };
    let nested_b = HardwareNestedPayload {
        id: 8,
        name: "hardware nested b ".repeat(1024),
        payload: vec![0x22; 64 * 1024],
    };
    let nested_c = HardwareNestedPayload {
        id: 9,
        name: "hardware nested c ".repeat(1024),
        payload: vec![0x33; 64 * 1024],
    };
    let msg = HardwareProstMessage {
        scalar: 42,
        name: "hardware dsa prost string ".repeat(4096),
        payload: Bytes::from(vec![0xa5; 256 * 1024]),
        repeated_names: vec![
            "hardware repeated string a ".repeat(1024),
            "hardware repeated string b ".repeat(1024),
        ],
        repeated_payloads: vec![vec![0x44; 96 * 1024], vec![0x55; 96 * 1024]],
        string_map: BTreeMap::from([
            (
                "string-map-key-a".to_owned(),
                "hardware string map value a ".repeat(1024),
            ),
            (
                "string-map-key-b".to_owned(),
                "hardware string map value b ".repeat(1024),
            ),
        ]),
        bytes_map: BTreeMap::from([
            ("bytes-map-key-a".to_owned(), vec![0x66; 80 * 1024]),
            ("bytes-map-key-b".to_owned(), vec![0x77; 80 * 1024]),
        ]),
        nested: Some(nested_a.clone()),
        repeated_nested: vec![nested_a.clone(), nested_b.clone()],
        nested_map: BTreeMap::from([
            ("nested-map-key-a".to_owned(), nested_b.clone()),
            ("nested-map-key-b".to_owned(), nested_c.clone()),
        ]),
        payload_oneof: Some(HardwarePayloadOneof::Payload(vec![0x88; 128 * 1024])),
        nested_oneof: Some(HardwareNestedOneof::Nested(nested_c)),
    };
    let mut expected = Vec::with_capacity(msg.encoded_len());
    msg.encode(&mut expected)
        .expect("synchronous prost encode succeeds");

    let source = tokio_stream::iter(std::iter::once(Ok::<_, Status>(msg.clone())));
    let mut body = pin!(EncodeBody::new_client(
        DsaAsyncProstEncoder::<HardwareProstMessage>::with_work_queue(
            BufferSettings::default(),
            work_queue,
        ),
        source,
        None,
        None,
    ));
    let waker = std::task::Waker::noop();
    let mut cx = Context::from_waker(waker);

    let (frame, pending_polls) = poll_next_frame_with_pending_count(&mut body, &mut cx);
    let data = frame.into_data().expect("got data frame");

    assert!(
        pending_polls > 0,
        "hardware DSA encode completed without yielding"
    );
    assert_eq!(data[0], 0);
    assert_eq!(
        u32::from_be_bytes(data[1..HEADER_SIZE].try_into().unwrap()) as usize,
        expected.len()
    );
    assert_eq!(&data[HEADER_SIZE..], expected.as_slice());

    let decoded =
        HardwareProstMessage::decode(&data[HEADER_SIZE..]).expect("encoded prost message decodes");
    assert_eq!(decoded, msg);
}

fn poll_next_frame<B>(
    body: &mut std::pin::Pin<&mut B>,
    cx: &mut Context<'_>,
) -> http_body::Frame<Bytes>
where
    B: Body<Data = Bytes, Error = Status>,
{
    poll_next_frame_with_pending_count(body, cx).0
}

fn poll_next_frame_with_pending_count<B>(
    body: &mut std::pin::Pin<&mut B>,
    cx: &mut Context<'_>,
) -> (http_body::Frame<Bytes>, usize)
where
    B: Body<Data = Bytes, Error = Status>,
{
    let mut pending_polls = 0;
    for _ in 0..1_000_000 {
        match body.as_mut().poll_frame(cx) {
            Poll::Ready(Some(Ok(frame))) => return (frame, pending_polls),
            Poll::Ready(Some(Err(status))) => panic!("encode failed: {status}"),
            Poll::Ready(None) => panic!("body ended before data"),
            Poll::Pending => {
                pending_polls += 1;
                core::hint::spin_loop();
            }
        }
    }

    panic!("timed out waiting for DSA encode completion")
}

